  }

  // Check for negative positions or other anomalies
  for (const card of cards) {
    if (parseFloat(card.position) < 0) {
      needsRenormalization = true;
      break;
    }
  }

  if (needsRenormalization) {
    // Renormalize positions: evenly space cards from 50 to (count-1)*50
    const spacing = 50;
    for (let i = 0; i < cards.length; i++) {
      const newPos = (i + 1) * spacing;
      await db.exec(
        'UPDATE cards SET position = $1 WHERE id = $2 AND column_id = $3',
        [newPos, cards[i].id, columnId]
      );
    }
  }

  return needsRenormalization;
}

