    } catch (err) {
      console.error('Error sending initial state:', err);
    }
  })();

  sseClients.add(res);

  req.on('close', () => {
    sseClients.delete(res);
  });
});

// ---- Start Server ----

async function start() {
  // Initialize database
  await getDb();
  console.log('Database initialized');

