    await db.query(
      'INSERT INTO cards (id, column_id, text, position, created_at) VALUES ($1, $2, $3, $4, $5)',
      [cardId, columnId, text, position, now]
    );

    const card = {
      id: cardId,
      columnId,
      text,
      position,
