body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  background: #0079bf;
  min-height: 100vh;
  padding: 20px;
}

#app {
  max-width: 1400px;
  margin: 0 auto;
}

h1 {
  color: white;
  margin-bottom: 20px;
  font-size: 24px;
}

.board {
  display: flex;
  gap: 16px;
  overflow-x: auto;
  padding-bottom: 20px;
  align-items: flex-start;
}

.column {
  background: #ebecf0;
  border-radius: 8px;
  min-width: 280px;
  max-width: 280px;
  padding: 12px;
  flex-shrink: 0;
}

.column-header {
  font-weight: 600;
  font-size: 14px;
  color: #172b4d;
  margin-bottom: 8px;
  padding: 4px 4px 8px;
}

.card-list {
