{"content": "// Kanban Board Frontend - Vanilla JS with SSE real-time sync

const API_BASE = '/api';

// State management
let boardState = { columns: [] };
let dragState = {
  cardId: null,
  sourceColumnId: null,
  sourceIndex: null,
};

// DOM references
const boardEl = document.getElementById('board');

// ---- API Functions ----

async function fetchBoard() {
  const res = await fetch(`${API_BASE}/board`);
  if (!res.ok) throw new Error(`Failed to fetch board: ${res.status}`);
  return res.json();
}

async function createCard(columnId, text) {
  const res = await fetch(`${API_BASE}/cards`, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ columnId, text }),
  });
  if (!res.ok) throw new Error(`Failed to create card: ${res.status}`);
  return res.json();
}

async function moveCard(cardId, { columnId, beforeId, afterId }) {
  const res = await fetch(`${API_BASE}/cards/${cardId}/move`, {
    method: 'PATCH',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ columnId, beforeId, afterId }),
  });
  if (!res.ok) throw new Error(`Failed to move card: ${res.status}`);
  return res.json();
}

// ---- Rendering ----

function renderBoard() {
